const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

const SECRET_KEY = process.env.SECRET_KEY || crypto.randomBytes(32);
const users = new Map();
const sessions = new Map();

function generateToken(payload) {
  const header = Buffer.from(JSON.stringify({alg: 'HS256', typ: 'JWT'})).toString('base64url');
  const body = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signature = crypto.createHmac('sha256', SECRET_KEY)
    .update(`${header}.${body}`)
    .digest('base64url');
  return `${header}.${body}.${signature}`;
}

function verifyToken(token) {
  if (!token || typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [header, body, providedSig] = parts;

  const expectedSig = crypto.createHmac('sha256', SECRET_KEY)
    .update(`${header}.${body}`)
    .digest('base64url');

  // Constant-time comparison to prevent timing attacks
  // First check lengths to avoid timingSafeEqual throwing
  if (providedSig.length !== expectedSig.length) {
    return null;
  }

  const sigBuffer = Buffer.from(providedSig, 'base64url');
  const expectedBuffer = Buffer.from(expectedSig, 'base64url');

  if (sigBuffer.length !== expectedBuffer.length) {
    return null;
  }

  if (!crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
    return null;
  }

  try {
    return JSON.parse(Buffer.from(body, 'base64url').toString());
  } catch {
    return null;
  }
}

function hashPassword(password, salt) {
  salt = salt || crypto.randomBytes(16).toString('hex');
  const hash = crypto.scryptSync(password, salt, 64).toString('hex');
  return { hash, salt };
}

function verifyPassword(password, storedHash, salt) {
  const { hash } = hashPassword(password, salt);
  const hashBuf = Buffer.from(hash, 'hex');
  const storedBuf = Buffer.from(storedHash, 'hex');
  if (hashBuf.length !== storedBuf.length) return false;
  return crypto.timingSafeEqual(hashBuf, storedBuf);
}

app.post('/api/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 64 || password.length < 8 || password.length > 128) {
    return res.status(400).json({ error: 'Invalid credentials format' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }
  const { hash, salt } = hashPassword(password);
  users.set(username, { hash, salt, role: 'user', mfaSecret: null });
  return res.status(201).json({ message: 'User created' });
});

app.post('/api/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });

  const user = users.get(username);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });

  if (!verifyPassword(password, user.hash, user.salt)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken({ sub: username, role: user.role, iat: Date.now() });
  sessions.set(username, { token, createdAt: Date.now() });
  return res.json({ token });
});

app.get('/api/profile', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }
  const token = authHeader.slice(7);
  const payload = verifyToken(token);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });

  const user = users.get(payload.sub);
  if (!user) return res.status(401).json({ error: 'User not found' });

  return res.json({ username: payload.sub, role: payload.role });
});

app.post('/api/admin/promote', (req, res) => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }
  const token = authHeader.slice(7);
  const payload = verifyToken(token);
  if (!payload) return res.status(401).json({ error: 'Invalid token' });

  // Authorization check: verify role from server-side state
  const currentUser = users.get(payload.sub);
  if (!currentUser || currentUser.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { targetUser } = req.body;
  if (!targetUser || !users.has(targetUser)) {
    return res.status(404).json({ error: 'User not found' });
  }

  const user = users.get(targetUser);
  user.role = 'admin';
  users.set(targetUser, user);
  return res.json({ message: `${targetUser} promoted to admin` });
});

app.listen(3000);
module.exports = app;
